"""Focused tests for reports.export.export_csv."""

import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic_header_and_rows(self):
        rows = [{'a': 1, 'b': 'x', 'c': True}]
        result = export_csv(rows, ['a', 'b', 'c'])
        self.assertEqual(result, 'a,b,c\r\n1,x,True\r\n')

    def test_ignores_unselected_fields(self):
        rows = [{'a': 1, 'b': 2, 'c': 3}]
        result = export_csv(rows, ['a', 'c'])
        self.assertEqual(result, 'a,c\r\n1,3\r\n')

    def test_missing_and_none_become_empty(self):
        rows = [{'a': None}, {'b': 5}]
        result = export_csv(rows, ['a', 'b'])
        self.assertEqual(result, 'a,b\r\n,\r\n,5\r\n')

    def test_rfc4180_minimal_quoting_and_doubling(self):
        rows = [{'a': 'plain', 'b': 'has,comma', 'c': 'has"quote'}]
        result = export_csv(rows, ['a', 'b', 'c'])
        self.assertEqual(result, 'a,b,c\r\nplain,"has,comma","has""quote"\r\n')

    def test_embedded_crlf_preserved(self):
        rows = [{'a': 'line1\r\nline2'}]
        result = export_csv(rows, ['a'])
        self.assertEqual(result, 'a\r\n"line1\r\nline2"\r\n')

    def test_embedded_lf_and_cr_preserved(self):
        rows = [{'a': 'x\ny', 'b': 'p\rq'}]
        result = export_csv(rows, ['a', 'b'])
        self.assertEqual(result, 'a,b\r\n"x\ny","p\rq"\r\n')

    def test_unicode_preserved(self):
        rows = [{'a': 'héllo ☃'}]
        result = export_csv(rows, ['a'])
        self.assertEqual(result, 'a\r\nhéllo ☃\r\n')

    def test_column_names_quoted_when_needed(self):
        rows = [{'a,b': 1, 'q"z': 2}]
        result = export_csv(rows, ['a,b', 'q"z'])
        self.assertEqual(result, '"a,b","q""z"\r\n1,2\r\n')

    def test_one_shot_generators(self):
        def gen_rows():
            yield {'x': 1}
            yield {'x': 2}

        def gen_cols():
            yield 'x'

        result = export_csv(gen_rows(), gen_cols())
        self.assertEqual(result, 'x\r\n1\r\n2\r\n')

    def test_empty_rows(self):
        result = export_csv([], ['a', 'b'])
        self.assertEqual(result, 'a,b\r\n')

    def test_empty_columns(self):
        result = export_csv([{'a': 1}, {'a': 2}], [])
        self.assertEqual(result, '\r\n\r\n\r\n')

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([{'a': 1}], ['a', 'a'])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([{'1': 'x'}], [1])

    def test_inputs_not_mutated(self):
        rows = [{'a': 1, 'b': 2}]
        columns = ['a']
        export_csv(rows, columns)
        self.assertEqual(rows, [{'a': 1, 'b': 2}])
        self.assertEqual(columns, ['a'])

    def test_str_conversion_for_other_values(self):
        rows = [{'a': 3.5, 'b': b'bytes', 'c': (1, 2)}]
        result = export_csv(rows, ['a', 'b', 'c'])
        self.assertEqual(result, 'a,b,c\r\n3.5,b"\'bytes\'",(1, 2)\r\n')

    def test_rows_iterable_consumed_once(self):
        consumed = []

        def gen():
            for i in range(3):
                consumed.append(i)
                yield {'v': i}

        result = export_csv(gen(), ['v'])
        self.assertEqual(result, 'v\r\n0\r\n1\r\n2\r\n')
        self.assertEqual(consumed, [0, 1, 2])


if __name__ == '__main__':
    unittest.main()

